CREATE VIEW mart_checkpoint_summary AS SELECT COUNT(*) parent_rows,SUM(primary_flag) primary_rows,SUM(process_flag) process_rows,SUM(payment_flag) payment_rows,SUM(CASE WHEN primary_flag=1 AND inspection_count=0 THEN 1 ELSE 0 END) primary_no_inspection,SUM(CASE WHEN primary_flag=1 AND inspection_count=1 THEN 1 ELSE 0 END) primary_single_inspection,SUM(CASE WHEN primary_flag=1 AND inspection_count>1 THEN 1 ELSE 0 END) primary_multiple_inspections FROM cases;
CREATE VIEW mart_process_clock_summary AS SELECT c.decision_period,COUNT(*) stage_rows,SUM(CASE WHEN s.clock_flag=1 THEN 1 ELSE 0 END) flagged_rows,SUM(CASE WHEN s.clock_flag=0 THEN 1 ELSE 0 END) restricted_rows,ROUND(AVG(julianday(s.decision_date)-julianday(s.notification_date)),2) avg_notification_to_decision_days FROM stages s JOIN cases c USING(case_id) WHERE s.stage_eligible=1 GROUP BY c.decision_period;
